          if (String(filters.year).indexOf("before:") === 0) params[`${datePrefix}_lte`] = `${String(filters.year).slice(7)}-12-31`;
          else { params[`${datePrefix}_gte`] = `${filters.year}-01-01`; params[`${datePrefix}_lte`] = `${filters.year}-12-31`; }
