        panProvider,
        panPassword,
        panTitle,
        panFileName,
        panFileId,
        resourceId,
        panSearchKeyword: continueIndexFirstValue([normalizedTarget.panSearchKeyword, source.panSearchKeyword, source.panSearchKeyword]),
